package jp.yaegaki.equipment;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;import android.content.*;import java.io.*;import java.util.*;import javax.crypto.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34)
public class StoreTest {
 @Test public void encryptedCrudAndBackupWithTwoPhotos()throws Exception{
 Context c=RuntimeEnvironment.getApplication();c.deleteDatabase("equipment.db");KeyGenerator kg=KeyGenerator.getInstance("AES");kg.init(256);Store store=new Store(c,kg.generateKey());String a=store.addPhoto("photo1".getBytes()),b=store.addPhoto("photo2".getBytes());JSONObject o=new JSONObject().put("id","test-1").put("name","受付PC").put("password","do-not-store-plaintext").put("photos",new JSONArray().put(new JSONObject().put("file",a).put("kind","本体")).put(new JSONObject().put("file",b).put("kind","設置風景")));store.save(o);assertEquals("受付PC",store.get("test-1").getString("name"));assertEquals(2,store.get("test-1").getJSONArray("photos").length());try(android.database.Cursor cur=store.getReadableDatabase().rawQuery("SELECT data FROM devices",null)){cur.moveToFirst();assertFalse(new String(cur.getBlob(0),"ISO-8859-1").contains("do-not-store-plaintext"));}
 ByteArrayOutputStream out=new ByteArrayOutputStream();store.exportBackup(out,"backup-test-123".toCharArray());try{store.importBackup(new ByteArrayInputStream(out.toByteArray()),"bad-password".toCharArray());fail();}catch(Exception expected){}assertEquals(1,store.all().size());assertEquals(1,store.importBackup(new ByteArrayInputStream(out.toByteArray()),"backup-test-123".toCharArray()));assertEquals(2,store.all().size());JSONObject copy=store.all().get(0);assertNotEquals("test-1",copy.getString("id"));assertArrayEquals("photo1".getBytes(),store.photo(copy.getJSONArray("photos").getJSONObject(0).getString("file")));store.delete("test-1");assertEquals(1,store.all().size());store.close();
 }
}
